import pandas as pd
import numpy as np
from datetime import timedelta


def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract high_ts from watermark (single row, single column)
    high_ts = watermark["high_ts"].iloc[0] if len(watermark) > 0 else pd.Timestamp.min

    # Filter events: keep only those with event_ts > high_ts
    new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # If no new events, return current snapshot
    if len(new_events) == 0:
        result = target_snapshot[["user_id", "email", "status", "status_ts"]].copy()
        return {"new_snapshot": result}

    # Sort events by user_id, then by event_ts, then by event_seq for deterministic processing
    new_events = new_events.sort_values(by=["user_id", "event_ts", "event_seq"]).reset_index(drop=True)

    # Create a working copy of the snapshot indexed by user_id
    snapshot_dict = {}
    for _, row in target_snapshot.iterrows():
        user_id = row["user_id"]
        snapshot_dict[user_id] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"]
        }

    # Process each event in order
    for _, event in new_events.iterrows():
        user_id = event["user_id"]
        event_ts = event["event_ts"]
        op = event["op"]
        email = event["email"]

        # Get current state or create new user
        if user_id not in snapshot_dict:
            current_state = {
                "email": None,
                "status": None,
                "status_ts": None
            }
        else:
            current_state = snapshot_dict[user_id]

        if op == "U":
            # Update operation
            if current_state["status"] is None:
                # New user: activate
                snapshot_dict[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }
            elif current_state["status"] == "ACTIVE":
                # Update active user
                snapshot_dict[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }
            elif current_state["status"] == "DELETED":
                # Resurrection check: strictly more than 7 days
                deletion_ts = current_state["status_ts"]
                days_since_deletion = (event_ts - deletion_ts).total_seconds() / (86400)

                # Strictly greater than 7 days (not >=)
                if days_since_deletion > 7:
                    snapshot_dict[user_id] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": event_ts
                    }
                # else: discard the update, deletion is sticky

        elif op == "D":
            # Delete operation: soft delete
            snapshot_dict[user_id] = {
                "email": current_state["email"] if current_state["email"] is not None else email,
                "status": "DELETED",
                "status_ts": event_ts
            }

    # Convert snapshot_dict back to DataFrame
    result_rows = []
    for user_id, state in snapshot_dict.items():
        result_rows.append({
            "user_id": user_id,
            "email": state["email"],
            "status": state["status"],
            "status_ts": state["status_ts"]
        })

    if result_rows:
        new_snapshot = pd.DataFrame(result_rows)
        # Ensure correct dtypes
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype("object")
        new_snapshot["status"] = new_snapshot["status"].astype("object")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"], utc=False)
        new_snapshot["status_ts"] = new_snapshot["status_ts"].astype("datetime64[us]")
    else:
        new_snapshot = pd.DataFrame(
            columns=["user_id", "email", "status", "status_ts"]
        )
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["status_ts"] = new_snapshot["status_ts"].astype("datetime64[us]")

    return {"new_snapshot": new_snapshot}
